effect.shader:

void main() {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    float distance = 1 - texColor.a;
    switch(mode) {
    case 0://Coarse+Fine
        distance = (1 - texColor.a) + ((texColor.r + texColor.g + texColor.b)/3/255);
        break;
    case 1://Coarse Only
        distance = 1 - texColor.a;
        break;
    case 2://Amplified Fine
        distance = 1 - ((texColor.r + texColor.g + texColor.b)/3);
        break;
    case 3://Coarse+AmplifiedFine
        distance = (1 - texColor.a) + ((texColor.r + texColor.g + texColor.b)/3/10);
        break;
    default:
        break;
    }

    distance *= 5.0;

    float lum = clamp((distance - clipLow) / (clipHigh - clipLow), 0.0,1.0);
    gl_FragColor = vec4(lum, lum, lum, 1.0);
}
